import{_ as e,o as a,c as r,a5 as c}from"./chunks/framework.a5no_H3L.js";const h=JSON.parse('{"title":"性能基准与调优","description":"本章提供 RabbitMQ 不同配置下的性能基准数据，以及调优方法论。","frontmatter":{},"headers":[],"relativePath":"rabbitmq/10-practice/chapter-06-performance-benchmark.md","filePath":"rabbitmq/10-practice/chapter-06-performance-benchmark.md"}'),l={name:"rabbitmq/10-practice/chapter-06-performance-benchmark.md"};function i(d,t,n,m,s,b){return a(),r("div",null,[...t[0]||(t[0]=[c('<h1 id="性能基准与调优" tabindex="-1" data-src-line="1" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">性能基准与调优 <a class="header-anchor" href="#性能基准与调优" aria-label="Permalink to &quot;性能基准与调优&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><p data-src-line="3" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">本章提供 RabbitMQ 不同配置下的性能基准数据，以及调优方法论。</p><p data-src-line="5" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">下面这些数字是未经实测验证的示例数量级，仅用于建立数量级直觉，不代表 RabbitMQ 在任何环境下的真实性能，也不应作为容量规划的输入。做容量规划前，必须用 PerfTest 在自己的环境复现；不同硬件、消息大小、网络条件、持久化与确认策略下，吞吐量差异可达数倍。</p></blockquote><h2 id="_1-测试环境" tabindex="-1" data-src-line="7" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">1. 测试环境 <a class="header-anchor" href="#_1-测试环境" aria-label="Permalink to &quot;1. 测试环境&quot;">​</a></h2><table tabindex="0"><thead data-src-line="9" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><tr data-src-line="9" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><th style="text-align:left;">配置</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="11" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><tr data-src-line="11" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">机器</td><td style="text-align:left;">4C8G SSD</td></tr><tr data-src-line="12" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">网络</td><td style="text-align:left;">同机房内网</td></tr><tr data-src-line="13" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">RabbitMQ</td><td style="text-align:left;">3.12</td></tr><tr data-src-line="14" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">Java</td><td style="text-align:left;">17</td></tr><tr data-src-line="15" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">消息大小</td><td style="text-align:left;">1KB</td></tr></tbody></table><h2 id="_2-性能基准" tabindex="-1" data-src-line="17" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">2. 性能基准 <a class="header-anchor" href="#_2-性能基准" aria-label="Permalink to &quot;2. 性能基准&quot;">​</a></h2><h3 id="_2-1-生产者" tabindex="-1" data-src-line="19" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">2.1 生产者 <a class="header-anchor" href="#_2-1-生产者" aria-label="Permalink to &quot;2.1 生产者&quot;">​</a></h3><table tabindex="0"><thead data-src-line="21" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><tr data-src-line="21" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><th style="text-align:left;">队列类型</th><th style="text-align:left;">逐条等待 Confirm</th><th style="text-align:left;">异步 Confirm</th><th style="text-align:left;">批量等待 Confirm</th></tr></thead><tbody data-src-line="23" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><tr data-src-line="23" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">Classic Queue</td><td style="text-align:left;">2,000 msg/s</td><td style="text-align:left;">25,000 msg/s</td><td style="text-align:left;">40,000 msg/s</td></tr><tr data-src-line="24" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">Quorum Queue</td><td style="text-align:left;">1,500 msg/s</td><td style="text-align:left;">10,000 msg/s</td><td style="text-align:left;">15,000 msg/s</td></tr><tr data-src-line="25" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">Stream Queue</td><td style="text-align:left;">5,000 msg/s</td><td style="text-align:left;">50,000 msg/s</td><td style="text-align:left;">100,000 msg/s</td></tr></tbody></table><blockquote data-src-line="27" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><p data-src-line="27" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">异步 Confirm 指客户端异步接收确认，批量等待指让多条消息同时处于未确认状态后再等待结果。二者是客户端组织确认的方式，可以配合使用，并非 RabbitMQ 提供的独立批量 Confirm 协议。表中数字为示意性的数量级示例，不附带实测依据。</p></blockquote><h3 id="_2-2-消费者" tabindex="-1" data-src-line="29" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">2.2 消费者 <a class="header-anchor" href="#_2-2-消费者" aria-label="Permalink to &quot;2.2 消费者&quot;">​</a></h3><table tabindex="0"><thead data-src-line="31" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><tr data-src-line="31" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><th style="text-align:left;">队列类型</th><th style="text-align:left;">prefetch=1</th><th style="text-align:left;">prefetch=10</th><th style="text-align:left;">prefetch=100</th></tr></thead><tbody data-src-line="33" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><tr data-src-line="33" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">Classic Queue</td><td style="text-align:left;">1,000 msg/s</td><td style="text-align:left;">10,000 msg/s</td><td style="text-align:left;">20,000 msg/s</td></tr><tr data-src-line="34" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">Quorum Queue</td><td style="text-align:left;">800 msg/s</td><td style="text-align:left;">8,000 msg/s</td><td style="text-align:left;">12,000 msg/s</td></tr><tr data-src-line="35" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">Stream Queue</td><td style="text-align:left;">5,000 msg/s</td><td style="text-align:left;">50,000 msg/s</td><td style="text-align:left;">100,000 msg/s</td></tr></tbody></table><blockquote data-src-line="37" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><p data-src-line="37" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">prefetch 约束的是未确认投递数，不是吞吐量的直接计算公式；其作用范围还受 QoS 配置影响（是否全局限制）。实际消费速率取决于消息处理耗时、确认方式（自动或手动）和并发模型，表中数字仅为示意性的数量级示例。</p></blockquote><h3 id="_2-3-延迟" tabindex="-1" data-src-line="39" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">2.3 延迟 <a class="header-anchor" href="#_2-3-延迟" aria-label="Permalink to &quot;2.3 延迟&quot;">​</a></h3><table tabindex="0"><thead data-src-line="41" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><tr data-src-line="41" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><th style="text-align:left;">指标</th><th style="text-align:left;">延迟</th><th style="text-align:left;">测量边界</th></tr></thead><tbody data-src-line="43" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><tr data-src-line="43" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">发布确认延迟</td><td style="text-align:left;">0.1~0.5ms</td><td style="text-align:left;">发布到收到对应 Publisher Confirm</td></tr><tr data-src-line="44" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">端到端延迟</td><td style="text-align:left;">1~5ms</td><td style="text-align:left;">发布到消费者收到消息</td></tr><tr data-src-line="45" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">Quorum 确认延迟</td><td style="text-align:left;">2~10ms</td><td style="text-align:left;">发布到收到 Quorum 对应 Confirm</td></tr></tbody></table><blockquote data-src-line="47" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><p data-src-line="47" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">表中数值为示意性的数量级示例，不附带统计口径，未覆盖 P95/P99 长尾。真实延迟受持久化、复制与批量落盘影响，需按明确起止事件实测得出，不能直接等同于单次磁盘写入耗时。</p></blockquote><h2 id="_3-调优方法论" tabindex="-1" data-src-line="49" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">3. 调优方法论 <a class="header-anchor" href="#_3-调优方法论" aria-label="Permalink to &quot;3. 调优方法论&quot;">​</a></h2><h3 id="_3-1-识别瓶颈" tabindex="-1" data-src-line="51" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">3.1 识别瓶颈 <a class="header-anchor" href="#_3-1-识别瓶颈" aria-label="Permalink to &quot;3.1 识别瓶颈&quot;">​</a></h3><p data-src-line="53" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">排查性能问题时，先对比发布速率、确认速率与消费速率，结合队列积压和资源指标定位瓶颈，而不是把某一现象直接归因到某个配置。</p><ul data-src-line="55" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><li data-src-line="55" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">发布速率低：检查生产者 CPU、消息序列化、网络、Confirm 延迟与未确认消息数。</li><li data-src-line="56" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">确认延迟高：检查队列类型、持久化与复制开销，以及 Broker 的 CPU、磁盘与网络。</li><li data-src-line="57" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">消费速率低：检查消费者数量、业务处理耗时、确认方式、prefetch 与客户端资源。</li><li data-src-line="58" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">队列持续积压：比较消息进入与离开队列的速率；进入速率长期高于离开速率，积压就会持续增长。</li></ul><p data-src-line="60" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">这些现象只能缩小排查范围，不能单独证明某个组件就是瓶颈。调整配置前，应先用指标和对照测试验证判断。</p><h3 id="_3-2-调优步骤" tabindex="-1" data-src-line="62" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">3.2 调优步骤 <a class="header-anchor" href="#_3-2-调优步骤" aria-label="Permalink to &quot;3.2 调优步骤&quot;">​</a></h3><ol data-src-line="64" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><li data-src-line="64" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">建立基线：固定队列类型、消息大小、持久化与确认策略，记录吞吐量、延迟和资源使用。</li><li data-src-line="65" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">逐步增加负载：每次只调整一个变量（生产者数量、消费者数量或 prefetch），避免同时改动多个参数。</li><li data-src-line="66" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">观察变化：记录吞吐量是否增长、延迟是否恶化，以及 CPU、内存、磁盘、网络的变化。</li><li data-src-line="67" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">定位瓶颈：结合客户端与 Broker 指标，区分客户端处理能力、网络、磁盘 I/O、队列处理与业务逻辑。</li><li data-src-line="68" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">复测验证：对候选配置重复测试，在接近目标生产负载下验证吞吐量、延迟与资源余量。</li></ol><p data-src-line="70" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">吞吐量不再增长时，先结合第 4 步的指标确认限制来自客户端、Broker、网络、磁盘 I/O 还是下游业务，再决定是否继续加并发；测试结论要同时看吞吐量、延迟和资源使用，不能只追求峰值。</p><h2 id="_4-常见调优项" tabindex="-1" data-src-line="72" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">4. 常见调优项 <a class="header-anchor" href="#_4-常见调优项" aria-label="Permalink to &quot;4. 常见调优项&quot;">​</a></h2><table tabindex="0"><thead data-src-line="74" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><tr data-src-line="74" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><th style="text-align:left;">项目</th><th style="text-align:left;">调优方向</th></tr></thead><tbody data-src-line="76" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><tr data-src-line="76" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">生产者</td><td style="text-align:left;">异步处理 Confirm，按确认延迟与内存占用调整未确认消息上限</td></tr><tr data-src-line="77" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">队列</td><td style="text-align:left;">根据吞吐量、持久化、消费语义与运维成本选择队列类型</td></tr><tr data-src-line="78" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">消费者</td><td style="text-align:left;">按处理耗时与确认方式调整 prefetch，必要时增加消费者</td></tr><tr data-src-line="79" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">消息</td><td style="text-align:left;">按网络带宽、CPU 与消息体积评估压缩和序列化格式</td></tr><tr data-src-line="80" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">连接</td><td style="text-align:left;">复用连接与 Channel，避免频繁创建关闭；注意客户端对 Channel 并发使用的约束</td></tr><tr data-src-line="81" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">Broker</td><td style="text-align:left;">先定位资源瓶颈，再有针对性地调整内存、磁盘与 TCP 参数</td></tr></tbody></table><h2 id="_5-性能陷阱" tabindex="-1" data-src-line="83" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md">5. 性能陷阱 <a class="header-anchor" href="#_5-性能陷阱" aria-label="Permalink to &quot;5. 性能陷阱&quot;">​</a></h2><table tabindex="0"><thead data-src-line="85" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><tr data-src-line="85" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><th style="text-align:left;">陷阱</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="87" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><tr data-src-line="87" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">逐条等待 Confirm</td><td style="text-align:left;">每条消息都等确认再发下一条，吞吐量受确认往返延迟限制；低吞吐场景下可能是合理的简单选择</td></tr><tr data-src-line="88" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">prefetch=1</td><td style="text-align:left;">限制未确认投递数量，处理耗时较长时无法充分利用消费者；耗时极短或需限制在途消息时反而合适</td></tr><tr data-src-line="89" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">大消息</td><td style="text-align:left;">提高网络传输、复制、客户端缓存与存储开销；是否压缩取决于可压缩性与 CPU 成本</td></tr><tr data-src-line="90" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">频繁声明</td><td style="text-align:left;">在每条消息处理路径重复声明交换器/队列，应在启动阶段完成声明</td></tr><tr data-src-line="91" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">消息堆积</td><td style="text-align:left;">进入速率持续高于消费速率时积压增长，增加内存、磁盘与恢复成本，需结合队列类型评估</td></tr><tr data-src-line="92" data-src-file="rabbitmq/10-practice/chapter-06-performance-benchmark.md"><td style="text-align:left;">事务</td><td style="text-align:left;">AMQP 事务与 Publisher Confirm 语义不同，事务需要额外的提交往返，吞吐量通常显著低于 Publisher Confirm；仅在需要事务语义时使用</td></tr></tbody></table>',26)])])}const p=e(l,[["render",i]]);export{h as __pageData,p as default};
